// 剪贴板自动捕获：用户复制到疑似日程的内容 → 桌宠气泡 + 检测卡确认。
//
// 隐私是这条链路的第一约束（剪贴板里过的是密码、2FA、API key）。四道门，前三道**都不读正文**：
//   ① changeCount 变化      —— 免权限的整数读取
//   ② Concealed/Transient/AutoGenerated 标记 —— 1Password 等会打标，命中即整条跳过
//   ③ detectPatterns([CalendarEvent])        —— 苹果端上数据检测器，不读正文、不触发系统提示
//   ④ 走到这里才第一次读正文 → 脱敏 → 上云
//
// 为什么①②③④全在原生 helper 里做：Electron 的 clipboard.availableFormats() 在 macOS 上
// 只返回 "text/plain"，**看不到 org.nspasteboard.* 标记**，read() 又无法区分「标记存在但值为空」
// 和「标记不存在」。所以主进程侧根本没法复核②。放在同一进程里，用 changeCount 前后夹紧，
// 才能保证「检查标记」和「读正文」针对的是同一份内容——否则用户在这毫秒级窗口里复制了密码，
// 就会绕过②。
import { execFile, spawn, type ChildProcessWithoutNullStreams } from 'child_process'
import clipboardDetectObjcTemplate from './native/clipboard-detect.m?raw'
import { app } from 'electron'
import { existsSync } from 'fs'
import { join } from 'path'
import { promisify } from 'util'
import type { LocalExtraction } from '@shared/types'
import { textHash } from '@shared/phash'
import { redactSensitive } from '@shared/sensitive'
import { CLIP_LIMITS, decideClipboardFastPath, decideClipboardParse } from '@shared/clip-gate'
import { CooldownMap } from '@shared/cooldown'
import { HINTS } from './capture'
import { getSettings } from './db'
import { ensureNativeHelperBinary } from './native-helper-cache'
import { cloudReady, parseToItems } from './parser'
import { applyExternalPetSay } from './pet/controller'
import {
  buildDetectionCards,
  buildLocalItem,
  parsedToExtraction,
  showDetectedCards,
  type DetectHit
} from './detection-cards'
import { isWatchPaused } from './screenwatch'
import { debugEvent, debugIsOpen } from './windows'

const execFileAsync = promisify(execFile)

// changeCount 只是一次极轻的整数读取：实测 800ms 轮询下 helper 跑 7 分钟只用掉 0.07 秒 CPU，
// 而轮询间隔直接决定「按下 ⌘C 到弹卡」的感知延迟，所以取更短的 250ms。
const POLL_MS = 250
/** 超过这个长度就不经管道回传（整篇文档/代码，不可能是待办）。业务长度门在 clip-gate 里。 */
const PIPE_MAX_CHARS = 20_000
const RESTART_BASE_MS = 2_000
const RESTART_MAX_MS = 60_000

// 占位符在编译前注入，保持轮询间隔/管道上限与 TS 侧常量一致（源码变化会触发 hash 重编）。
const HELPER_OBJC_SRC = clipboardDetectObjcTemplate
  .replace('__POLL_MS__', String(POLL_MS))
  .replace('__PIPE_MAX_CHARS__', String(PIPE_MAX_CHARS))



interface ClipHelperHit {
  type: 'hit'
  text: string
  app: string
  bundleId: string
  /** DDMatchCalendarEvent 解出的本地起始时刻；解不出时缺省 */
  startIso?: string
  endIso?: string
  allDay?: boolean
}
type ClipHelperEvent =
  | ClipHelperHit
  | { type: 'skip'; reason: string }
  | { type: 'ready' }
  | { type: 'unsupported' }

function binDir(): string {
  return join(app.getPath('userData'), 'bin')
}

let ensured: Promise<string> | null = null

async function ensureHelperBinary(): Promise<string> {
  if (process.platform === 'win32') return (await import('./platform/windows-helper.ts')).windowsHelperPath()
  if (process.platform !== 'darwin') throw new Error('Unsupported desktop platform')
  return ensureNativeHelperBinary({
    directory: binDir(),
    binaryName: 'clipboard-detect-v1',
    source: HELPER_OBJC_SRC,
    compile: async (src, bin) => {
      await execFileAsync('/usr/bin/xcrun', [
        'clang',
        '-fobjc-arc',
        '-O2',
        '-framework',
        'AppKit',
        '-framework',
        'Foundation',
        '-o',
        bin,
        src
      ])
    }
  })
}

let child: ChildProcessWithoutNullStreams | null = null
let stopped = true
let lifecycleGeneration = 0
let restartTimer: ReturnType<typeof setTimeout> | null = null
let restartAttempts = 0
let unsupported = false
/** 同内容冷却表 */
const cooldown = new CooldownMap(CLIP_LIMITS.cooldownMs)
let lastParseAtMs: number | null = null
let parseAbort: AbortController | null = null

function parseLine(line: string): ClipHelperEvent | null {
  if (!line) return null
  try {
    const value = JSON.parse(line) as Partial<Omit<ClipHelperHit, 'type'>> & { type?: unknown; reason?: unknown }
    if (!value || typeof value !== 'object') return null
    if (value.type === 'ready' || value.type === 'unsupported') return { type: value.type }
    if (value.type === 'skip' && typeof value.reason === 'string') return { type: 'skip', reason: value.reason.slice(0, 80) }
    if (value.type !== 'hit' || typeof value.text !== 'string' || !value.text || value.text.length > PIPE_MAX_CHARS ||
        typeof value.app !== 'string' || typeof value.bundleId !== 'string') return null
    return {
      type: 'hit', text: value.text, app: value.app.slice(0, 160), bundleId: value.bundleId.slice(0, 160),
      startIso: typeof value.startIso === 'string' ? value.startIso.slice(0, 32) : undefined,
      endIso: typeof value.endIso === 'string' ? value.endIso.slice(0, 32) : undefined,
      allDay: typeof value.allDay === 'boolean' ? value.allDay : undefined
    }
  } catch {
    return null
  }
}

function excludedApp(appName: string, bundleId: string): boolean {
  const list = getSettings().screenSenseExcludedApps
  if (!list.length) return false
  const name = appName.trim().toLowerCase()
  const bundle = bundleId.trim().toLowerCase()
  return list.some((entry) => {
    const e = entry.trim().toLowerCase()
    return !!e && (e === name || e === bundle)
  })
}

async function handleHit(event: ClipHelperHit): Promise<void> {
  if (stopped) return
  // 这三条早退必须留痕：用户的感受是「复制了但毫无反应」，没有日志就无从判断卡在哪
  if (parseAbort) {
    debugEvent('clip', '上一条仍在解析，本条跳过')
    return
  }
  const settings = getSettings()
  if (!settings.clipWatchEnabled) {
    debugEvent('clip', '剪贴板自动捕获已关闭')
    return
  }
  if (isWatchPaused()) {
    debugEvent('clip', '已从托盘暂停，剪贴板一并停用')
    return
  }

  // 本地快路：macOS 已经把时间结构化解出来了，短句直接成卡，不必等模型 8 秒
  const fast = decideClipboardFastPath({
    text: event.text,
    startIso: event.startIso,
    endIso: event.endIso,
    allDay: event.allDay,
    nowMs: Date.now()
  })
  if (!fast.fast && !cloudReady()) {
    debugEvent('clip', '解析服务未就绪，跳过')
    return
  }

  const now = Date.now()
  cooldown.sweep(now)
  const hash = textHash(event.text)
  const decision = decideClipboardParse({
    text: event.text,
    nowMs: now,
    cooldownUntilMs: cooldown.untilMs(hash),
    lastParseAtMs,
    excludedApp: excludedApp(event.app, event.bundleId),
    usesModel: !fast.fast
  })
  if (!decision.run) {
    debugEvent('clip', `不解析：${decision.reason}`)
    return
  }
  cooldown.start(hash, now)

  if (fast.fast) {
    debugEvent('clip', `本地直出（${fast.isoTime}${fast.deadline ? ' 截止' : ''}），未调模型`)
    const extraction: LocalExtraction = {
      title: fast.title,
      isoTime: fast.isoTime,
      deadline: fast.deadline,
      belongsToUser: 'uncertain', // 本地只解得出时间，判不了归属，交给用户在卡上确认
      hits: [],
      confidence: 0.7,
      strong: true
    }
    presentCards(
      [{ extraction, item: buildLocalItem(extraction, '剪贴板识别') }],
      event.text,
      event.app,
      settings.screenSensePopup
    )
    return
  }

  // 命中或未命中都冷却：同一段内容反复复制时不重复跑模型
  lastParseAtMs = now
  const controller = new AbortController()
  parseAbort = controller
  try {
    // 上云前脱敏：凭据/证件/卡号的值打码（第②道门管不到没打标记的密码）
    const redacted = redactSensitive(event.text)
    if (redacted.hits.length) debugEvent('clip', `已脱敏：${redacted.hits.join('、')}`)
    debugEvent('clip', `CalendarEvent 命中，解析中（${redacted.text.length} 字，来自 ${event.app || '未知'}）`)

    const items = await parseToItems({ text: redacted.text, hint: HINTS.clipboard_text, signal: controller.signal })
    if (controller.signal.aborted || stopped || isWatchPaused() || !getSettings().clipWatchEnabled ||
        excludedApp(event.app, event.bundleId)) return
    // 明确是别人的事就不记不弹：剪贴板是「用户主动复制了一段内容」，从群消息里复制到
    // 别人的安排很常见，全都进记忆只会把历史刷满。屏幕路径条目多、需要回看，故不同口径。
    const hits = items.filter((item) => item.belongs_to_user !== 'no')
    if (!hits.length) {
      debugEvent('clip', '云端未发现明确待办')
      return
    }
    presentCards(
      hits.map((item) => ({ extraction: parsedToExtraction(item), item })),
      redacted.text,
      event.app,
      getSettings().screenSensePopup
    )
  } catch (e) {
    if (!controller.signal.aborted)
      debugEvent('clip', `解析失败：${e instanceof Error ? e.message : String(e)}`)
  } finally {
    if (parseAbort === controller) parseAbort = null
  }
}

/** 记入「记忆」历史 → 挑出该弹的 → 弹卡 + 桌宠气泡。快路与模型路共用。 */
function presentCards(
  hits: DetectHit[],
  sourceText: string,
  app: string,
  popup: boolean
): void {
  const cards = buildDetectionCards({ hits, sourceText, app: app || null, popup })
  if (!cards.length) {
    debugEvent('clip', '没有需要弹卡的候选（已存在或弱信号）')
    return
  }
  // 剪贴板卡与屏幕感知卡同口径：倒计时 + 底部进度条，走满自动忽略；悬停即暂停。
  debugEvent('clip', cards.length > 1 ? `弹出清单卡：${cards.length} 条` : '弹出检测卡')
  showDetectedCards(cards)
  applyExternalPetSay(cards.length > 1 ? `发现 ${cards.length} 个日程~` : '发现一个日程~', 'waiting')
}

function scheduleRestart(reason: string, generation: number): void {
  if (stopped || generation !== lifecycleGeneration || restartTimer) return
  if (child) {
    child = null
  }
  restartAttempts += 1
  const delay = Math.min(RESTART_MAX_MS, RESTART_BASE_MS * 2 ** (restartAttempts - 1))
  debugEvent('clip', `helper 退出（${reason}），${Math.round(delay / 1000)}s 后重启`)
  restartTimer = setTimeout(() => {
    if (stopped || generation !== lifecycleGeneration) return
    restartTimer = null
    void launch()
  }, delay)
  restartTimer.unref?.()
}

async function launch(): Promise<void> {
  if (stopped || child || unsupported) return
  const generation = lifecycleGeneration
  try {
    if (ensured) {
      const cached = await ensured.catch(() => '')
      if (stopped || generation !== lifecycleGeneration || child) return
      if (!existsSync(cached)) ensured = null
    }
    if (!ensured) ensured = ensureHelperBinary()
    const bin = await ensured
    if (stopped || generation !== lifecycleGeneration || child) return

    const proc = process.platform === 'win32'
      ? (await import('./platform/windows-helper.ts')).spawnWindowsHelper('clipboard-watch')
      : spawn(bin, [], { stdio: ['pipe', 'pipe', 'pipe'] })
    if (stopped || generation !== lifecycleGeneration || child) { proc.kill(); return }
    child = proc
    const current = (): boolean => !stopped && generation === lifecycleGeneration && child === proc
    let buffer = ''
    proc.stdout.setEncoding('utf8')
    proc.stdout.on('data', (chunk: string) => {
      if (!current()) return
      buffer += chunk
      if (buffer.length > 256 * 1024) { proc.kill(); scheduleRestart('output overflow', generation); return }
      const lines = buffer.split(/\r?\n/)
      buffer = lines.pop() ?? ''
      for (const line of lines) {
        const event = parseLine(line.trim())
        if (!event) continue
        if (event.type === 'unsupported') {
          // macOS < 15.4 没有 detectPatterns。绝不退化成「直接轮询读正文」——
          // 那会把这条链路的隐私优势全部丢掉。
          unsupported = true
          debugEvent('clip', process.platform === 'win32' ? 'Windows 剪贴板检测不可用' : '系统低于 macOS 15.4，剪贴板自动捕获不可用')
          stopClipWatch()
          return
        }
        if (event.type === 'ready') {
          restartAttempts = 0
          debugEvent('clip', '剪贴板感知已就绪')
        }
        // nopattern 是高频事件（每次复制非日程内容都会触发），只在调试窗开着时上报，
        // 否则日志会被刷爆；其余 skip 都罕见且有诊断价值，无条件记录。
        if (event.type === 'skip' && (event.reason !== 'nopattern' || debugIsOpen()))
          debugEvent('clip', `跳过：${event.reason}`)
        if (event.type === 'hit') void handleHit(event)
      }
    })
    proc.stderr.setEncoding('utf8')
    proc.stderr.on('data', (chunk: string) => {
      if (!current()) return
      const detail = chunk.trim().slice(0, 160)
      if (detail) debugEvent('clip', `helper stderr：${detail}`)
    })
    proc.once('error', (error) => {
      if (current()) scheduleRestart(error.message, generation)
    })
    proc.once('exit', (code, signal) => {
      if (current()) scheduleRestart(`code=${code ?? 'null'} signal=${signal ?? 'none'}`, generation)
    })
  } catch (e) {
    scheduleRestart(e instanceof Error ? e.message : String(e), generation)
  }
}

export function startClipWatch(): void {
  if ((process.platform !== 'darwin' && process.platform !== 'win32') || unsupported) return
  if (!stopped) return
  stopped = false
  void launch()
}

export function stopClipWatch(): void {
  stopped = true
  lifecycleGeneration += 1
  parseAbort?.abort()
  parseAbort = null
  if (restartTimer) clearTimeout(restartTimer)
  restartTimer = null
  if (child) {
    child.kill()
    child = null
  }
  cooldown.clear()
}

/** 跟随 clipWatchEnabled 设置启停（启动时与存设置时调用）。 */
export function applyClipWatchSettings(): void {
  if (getSettings().clipWatchEnabled) startClipWatch()
  else stopClipWatch()
}
